import math, sympy as sp
def rising(v,n): return math.prod(v+i for i in range(n))
def cvec(g,a): return [math.comb(g,j)*(-1)**(g-j)*rising(a,g-j)*rising(4-a,j) for j in range(g+1)]
def pvec(g,a,m):
 c=cvec(g,a); return [m*c[0]]+[(m+j)*c[j]+(m+j-1-g)*c[j-1] for j in range(1,g+1)]+[m*c[g]]
def col(g,a,m):
 d=1-g-(a+m); s=-a-g if d>0 else -a-g+abs(d); sg=1 if d>0 else -1
 return {s+j:sg*x for j,x in enumerate(pvec(g,a,m)) if x}
def comp(g,k,q):
 cen=1-g; return [col(g,a,m) for a in range(0,2*k+1,2) for m in (cen-q-a,cen+q-a)]
def defect(g,a,q):
 c=cvec(g,a); J=[c[0]]+[c[j]+c[j-1] for j in range(1,g+1)]+[c[g]]
 out={}
 for s,sg in [(-a-g,-2),(-a-g+q+2,2)]:
  for j,x in enumerate(J): out[s+j]=out.get(s+j,0)+sg*x
 return {r:x for r,x in out.items() if x}
def member(cols,v):
 rows=sorted(set(v)|{r for c in cols for r in c})
 A=sp.Matrix([[c.get(r,0) for c in cols] for r in rows]); b=sp.Matrix([v.get(r,0) for r in rows])
 return A.rank()==A.row_join(b).rank(), A.rank(), len(cols), len(rows)
res=[]
for g in range(2,9):
 for k in range(2,7):
  for q in range(1,9):
   cols=comp(g,k,q+2)
   for a in range(0,2*k+1,2):
    ok,r,n,nr=member(cols,defect(g,a,q))
    res.append((ok,g,k,q,a,r,n,nr))
print('total',len(res),'in',sum(x[0] for x in res),'out',sum(not x[0] for x in res))
print('first_in',next((x for x in res if x[0]),None))
print('first_out',next((x for x in res if not x[0]),None))
print('all_by_gq',[(g,q,all(x[0] for x in res if x[1]==g and x[3]==q)) for g in range(2,9) for q in range(1,9)])
